CAN readonly IN self_unfolding_fold_v1(
  current: Atom,
  carrier_grammar: Atom,
  genealogy: Atom
) -> Atom {
  SAME current.realization_kind {
    "F3_ELEMENT_POLYHEDRA_BASIS" -> NONE
    _ -> {
      THIS successor = fold_internal_realization_v1.call(current, carrier_grammar)
      THIS successor_genealogy = TOGETHER {
        realizations: genealogy.realizations + [successor]
        transitions: genealogy.transitions + [TOGETHER {
          source: current.realization_digest
          target: successor.realization_digest
        }]
      }
      NO IN self_unfolding_fold_v1.call(
        successor, carrier_grammar, successor_genealogy
      )
    }
  }

  THIS closure = elemental_closure_v1.call(current, carrier_grammar)
  SAME closure.verdict { "IF_THEN" -> NONE _ -> NO IN fold_obligation_v1.call(
    closure.verdict, closure.first_failure_locus, closure
  ) }
  NO IN TOGETHER {
    kind: "SELF_UNFOLDING_ELEMENT_BASIS_RESULT_V1"
    verdict: "IF_THEN"
    invocation_count: 1
    internal_unfolding_count: genealogy.transitions.count
    fold_arity: 1
    fold_identity: "SELF_UNFOLDING_FOLD_V1"
    realizations: genealogy.realizations
    element_basis: current.structural_whole
    fold_genealogy_receipt: TOGETHER {
      kind: "FOLD_GENEALOGY_RECEIPT_V1"
      verdict: "IF_THEN"
      fold_identity: "SELF_UNFOLDING_FOLD_V1"
      invocation_count: 1
      transitions: genealogy.transitions
    }
    elemental_closure_receipt: closure
    physical_element_correspondence: "MAYBE"
    host_selected_stopping_depth: 0
    scale_specific_fold_functions: 0
    element_name_constructors: 0
  }

CAN readonly IN admit_horizontal_cover_v1(source: Atom, target: Atom, proposal: Atom) -> Atom {
  SAME source.verdict { "IF_THEN" -> NONE _ -> NO IN source }
  SAME target.verdict { "IF_THEN" -> NONE _ -> NO IN target }
  SAME source.arrangement.multiset { target.arrangement.multiset -> NONE _ -> NO IN TOGETHER {
    kind: "HORIZONTAL_COVER_V1" verdict: "NOT_SAME"
    first_failure_locus: "MULTISET_CHANGED"
  } }
  SAME proposal.vertical_conversion { false -> NONE _ -> NO IN TOGETHER {
    kind: "HORIZONTAL_COVER_V1" verdict: "NOT_SAME"
    first_failure_locus: "VERTICAL_PROPOSAL_AT_HORIZONTAL_BOUNDARY"
  } }
  SAME proposal.complete_directional_witness {
    true -> NONE
    _ -> NO IN TOGETHER {
      kind: "HORIZONTAL_COVER_V1" verdict: "MAYBE"
      first_failure_locus: "ANTISYMMETRIC_DIRECTIONAL_INVARIANT"
    }
  }
  NO IN TOGETHER {
    kind: "HORIZONTAL_COVER_V1" verdict: "IF_THEN"
    source: source.world_identity target: target.world_identity
    multiset: source.arrangement.multiset
    genealogy: proposal.genealogy
  }
